// Existing Engine history projection only; no setup grant, transport or executor.
import assert from 'node:assert/strict';
import {Engine,memoryStore} from '../static/engine.mjs';
import * as wire from '../static/wire.mjs';
const e=new Engine({store:memoryStore(),base:'https://synthetic.invalid',fetch:()=>{throw Error('unexpected network');}});
const keys=await wire.newKeys(),pub=await wire.publicEntry(keys,'alice/browser');
e.keys=keys;e.address=pub.address;e.fp=await wire.fingerprint(pub);
const roster=await wire.newRoster(keys,e.address,'Alice');e.me=await e.personRecord([roster],'self',null);
const otherKeys=await wire.newKeys(),otherPub=await wire.publicEntry(otherKeys,'bob/desk'),otherFP=await wire.fingerprint(otherPub),otherRoster=await wire.newRoster(otherKeys,otherPub.address,'Bob');
const other=await e.personRecord([otherRoster],'pinned',null);
await e.store.write([{s:'persons',k:other.person,v:other},{s:'kv',k:'person',v:e.me}]);
const root=await wire.newRoot(keys,{person:e.me.person,roster:e.me.hash,address:e.address,fingerprint:e.fp},{person:other.person,roster:other.hash});
const conv=await wire.rootID(root),rootJSON=wire.rootJSON(root),id=wire.newID();
const route=wire.parseReceiverRoute({op:'request',host:e.address,host_key:e.fp,request_ref:id,request_digest:'a'.repeat(64),delegation_id:wire.newID()});
const source={id,lid:id,ts:1700000000,at:1700000000000,conv,from:otherPub.address,fp:otherFP,kind:'question',body:'Exact inert history',receiver_route:route,attachments:[{name:'selected.txt',size:3,sha256:'b'.repeat(64),blob:{id:wire.newID(),size:80,sha256:'c'.repeat(64)}}]};
const item=e.itemOf(source,false),raw=wire.historyJSON(item);
assert.deepEqual(item.receiver_route,route);assert.equal(wire.parseHistory(raw).receiver_route.request_digest,route.request_digest);
assert.ok(!raw.includes(source.attachments[0].blob.id),'history exposes only plaintext manifests');
const ops=await e.admitHistory({conv,root:rootJSON,body:raw},{from:'alice/sibling'},root,[]);
const record=ops.find(o=>o.s==='inbox').v;
assert.deepEqual(record.receiver_route,route);assert.equal(record.history,true);assert.equal(record.state,'');assert.equal(record.replica,true);
assert.equal(record.from,otherPub.address);assert.equal(record.fp,otherFP);assert.equal(record.attachments[0].blob,null);
assert.ok(!ops.some(o=>o.s==='outbox'||o.s==='kv'),'inert imported history creates no setup/binding/send');
await e.store.write(ops);const restored=new Engine({store:e.store,base:e.base,fetch:e.fetch});restored.address=e.address;restored.fp=e.fp;
assert.equal(wire.historyJSON(restored.itemOf(await e.store.get('inbox',id),false)),raw);
const legacy={...source};delete legacy.receiver_route;
assert.ok(!('receiver_route' in e.itemOf(legacy,false)));assert.ok(!wire.historyJSON(e.itemOf(legacy,false)).includes('receiver_route'));
for(const op of ['delegate','ready','catalog'])assert.throws(()=>wire.parseHistory(wire.historyJSON({...item,receiver_route:{...route,op}})));
console.log('Engine receiver projection ok: retained inert route/author/manifests after stored reload, legacy absence, setup-history refusal');
